1	#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
2	//! After any sequence of edits, a watch session's output equals a cold extract of the same files. A small project (a
3	//! component whose props come from an imported type, a re-exported type, wrappers, a `.d.ts` declaration, a file whose
4	//! export is toggled) takes a seeded random sequence of edits: change a prop's type, add or remove a prop, rename an
5	//! exported type, change an import path, toggle an export, delete a file and put it back, break a file and fix it. After
6	//! every edit the eager session's output, serialized as the CLI's canonical JSON with `stats` dropped, and the RDT
7	//! output, equal a fresh `extract()` of the directory with no cache; a lazy session that was asked for every component
8	//! before the edit gives each component exactly the cold entry. A failure names the seed, the step and every edit so far,
9	//! so it replays: `SEED=<n> cargo nextest run -p caliper-docgen-core session_equals_cold`.
10	
11	use caliper_docgen_core::pipeline::{HtmlAttributeMode, PipelineOptions, WatchSession, extract, rdt};
12	use caliper_docgen_core::types::ExtractionOutput;
13	use camino::{Utf8Path, Utf8PathBuf};
14	use serde_json::Value;
15	
16	const SEEDS: u64 = 20;
17	const EDITS: usize = 12;
18	
19	/// A small deterministic generator: the model is reproducible without a dependency.
20	struct Lcg(u64);
21	
22	impl Lcg {
23	    fn below(&mut self, n: usize) -> usize {
24	        self.0 = self.0.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
25	        usize::try_from((self.0 >> 33) % n as u64).unwrap()
26	    }
27	}
28	
29	/// The project's files. Each is rendered from the model's state, so an edit changes one field and rewrites one file.
30	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
31	enum File {
32	    /// The props type `Shared<n>`, with `size` and a number of extra members.
33	    Types,
34	    /// Re-exports the props type from `types.ts`.
35	    Index,
36	    /// `Button`, whose props extend the imported type.
37	    Button,
38	    /// `Card`, whose props are the local declaration's type.
39	    Card,
40	    /// `Fancy` (a `forwardRef`) and `Memoed` (a `memo`), each wrapping one of the components.
41	    Wrapped,
42	    /// A `.d.ts` that declares `Local`, the props type of `Card`.
43	    Local,
44	    /// `Toggle`, whose `export` comes and goes.
45	    Toggle,
46	}
47	
48	const FILES: [File; 7] = [File::Types, File::Index, File::Button, File::Card, File::Wrapped, File::Local, File::Toggle];
49	
50	impl File {
51	    fn name(self) -> &'static str {
52	        match self {
53	            File::Types => "types.ts",
54	            File::Index => "index.ts",
55	            File::Button => "Button.tsx",
56	            File::Card => "Card.tsx",
57	            File::Wrapped => "Wrapped.tsx",
58	            File::Local => "local.d.ts",
59	            File::Toggle => "Toggle.tsx",
60	        }
61	    }
62	}
63	
64	#[derive(Clone)]
65	struct State {
66	    /// The name `types.ts` exports its props type as, `Shared<n>`.
67	    types_name: usize,
68	    /// The name `index.ts` re-exports, and the name `Button` imports.
69	    index_name: usize,
70	    button_name: usize,
71	    /// `size`'s type in `types.ts`.
72	    size_is_number: bool,
73	    /// Extra members of the shared type, and of `Button`'s own props.
74	    shared_extra: usize,
75	    own_extra: usize,
76	    /// Whether `Button` imports its type through `./index` or straight from `./types`.
77	    button_via_index: bool,
78	    /// Which component `Fancy` wraps, and whether `Memoed` wraps `Button`.
79	    fancy_wraps_card: bool,
80	    /// `Local`'s members, and `Card`'s own prop type.
81	    local_extra: usize,
82	    card_label_is_number: bool,
83	    toggle_exported: bool,
84	    button_exported: bool,
85	    exists: [bool; 7],
86	    broken: [bool; 7],
87	}
88	
89	impl State {
90	    fn new() -> State {
91	        State {
92	            types_name: 0,
93	            index_name: 0,
94	            button_name: 0,
95	            size_is_number: false,
96	            shared_extra: 1,
97	            own_extra: 1,
98	            button_via_index: true,
99	            fancy_wraps_card: false,
100	            local_extra: 1,
101	            card_label_is_number: false,
102	            toggle_exported: true,
103	            button_exported: true,
104	            exists: [true; 7],
105	            broken: [false; 7],
106	        }
107	    }
108	
109	    fn render(&self, file: File) -> String {
110	        let members =
111	            |prefix: &str, n: usize| -> String { (0..n).map(|i| format!("{prefix}{i}?: string; ")).collect() };
112	        let mut source = match file {
113	            File::Types => format!(
114	                "export interface Shared{} {{ size?: {}; {}}}\nexport type Tone = 'a' | 'b';\n",
115	                self.types_name,
116	                if self.size_is_number { "number" } else { "string" },
117	                members("m", self.shared_extra),
118	            ),
119	            File::Index => format!(
120	                "export type {{ Shared{0} }} from './types';\nexport type {{ Tone }} from './types';\n",
121	                self.index_name
122	            ),
123	            File::Button => format!(
124	                "import type {{ Shared{name} }} from '{path}';\n\
125	                 export interface ButtonProps extends Shared{name} {{ onClick?: () => void; {own}}}\n\
126	                 {export}function Button(props: ButtonProps) {{ return <button>{{props.size}}</button>; }}\n",
127	                name = self.button_name,
128	                path = if self.button_via_index { "./index" } else { "./types" },
129	                own = members("own", self.own_extra),
130	                export = if self.button_exported { "export " } else { "" },
131	            ),
132	            File::Card => format!(
133	                "import type {{ Local }} from './local';\n\
134	                 export interface CardProps extends Local {{ label?: {}; tone?: 'a' | 'b' }}\n\
135	                 export const Card = (props: CardProps) => <section>{{props.label}}</section>;\n",
136	                if self.card_label_is_number { "number" } else { "string" },
137	            ),
138	            File::Wrapped => format!(
139	                "import * as React from 'react';\n\
140	                 import {{ Button }} from './Button';\n\
141	                 import {{ Card }} from './Card';\n\
142	                 export const Fancy = React.forwardRef<HTMLElement, React.ComponentProps<typeof {}>>((props, ref) => null);\n\
143	                 export const Memoed = React.memo(Button);\n",
144	                if self.fancy_wraps_card { "Card" } else { "Button" },
145	            ),
146	            File::Local => format!("export interface Local {{ {}}}\n", members("l", self.local_extra)),
147	            File::Toggle => format!(
148	                "interface ToggleProps {{ on?: boolean }}\n{}function Toggle(props: ToggleProps) {{ return <i>{{String(props.on)}}</i>; }}\n",
149	                if self.toggle_exported { "export " } else { "" },
150	            ),
151	        };
152	        if self.broken[index(file)] {
153	            source.push_str("export const = {{{ ;\n");
154	        }
155	        source
156	    }
157	}
158	
159	fn index(file: File) -> usize {
160	    FILES.iter().position(|candidate| *candidate == file).unwrap()
161	}
162	
163	/// Applies one random edit to the state and the files, and returns the file it touched and a name for the edit.
164	fn edit(state: &mut State, root: &Utf8Path, rng: &mut Lcg) -> (File, String) {
165	    let touch = |state: &State, file: File| {
166	        let path = root.join(file.name());
167	        if state.exists[index(file)] {
168	            std::fs::write(&path, state.render(file)).unwrap();
169	        } else {
170	            // A file already gone (a change to a deleted file's model state) stays gone.
171	            drop(std::fs::remove_file(&path));
172	        }
173	    };
174	    let (file, what) = match rng.below(9) {
175	        0 => {
176	            // A prop's type changes: the shared type's `size`, or `Card`'s `label`.
177	            if rng.below(2) == 0 {
178	                state.size_is_number = !state.size_is_number;
179	                (File::Types, "change size's type")
180	            } else {
181	                state.card_label_is_number = !state.card_label_is_number;
182	                (File::Card, "change label's type")
183	            }
184	        }
185	        1 => {
186	            // A prop comes or goes: a member of the shared type, `Button`'s own, or the declaration's.
187	            match rng.below(3) {
188	                0 => {
189	                    state.shared_extra = (state.shared_extra + 1) % 3;
190	                    (File::Types, "add or remove a shared member")
191	                }
192	                1 => {
193	                    state.own_extra = (state.own_extra + 1) % 3;
194	                    (File::Button, "add or remove an own prop")
195	                }
196	                _ => {
197	                    state.local_extra = (state.local_extra + 1) % 3;
198	                    (File::Local, "add or remove a declared member")
199	                }
200	            }
201	        }
202	        2 => {
203	            // The exported type is renamed in one of the three files that name it.
204	            match rng.below(3) {
205	                0 => {
206	                    state.types_name = (state.types_name + 1) % 2;
207	                    (File::Types, "rename the type where it is declared")
208	                }
209	                1 => {
210	                    state.index_name = (state.index_name + 1) % 2;
211	                    (File::Index, "rename the type where it is re-exported")
212	                }
213	                _ => {
214	                    state.button_name = (state.button_name + 1) % 2;
215	                    (File::Button, "rename the type where it is imported")
216	                }
217	            }
218	        }
219	        3 => {
220	            // Delete a file that exists.
221	            let alive: Vec<File> = FILES.iter().copied().filter(|file| state.exists[index(*file)]).collect();
222	            let file = alive[rng.below(alive.len())];
223	            state.exists[index(file)] = false;
224	            (file, "delete a file")
225	        }
226	        4 => {
227	            // Put a deleted file back, or, with none gone, touch one unchanged.
228	            let gone: Vec<File> = FILES.iter().copied().filter(|file| !state.exists[index(*file)]).collect();
229	            if gone.is_empty() {
230	                (FILES[rng.below(FILES.len())], "rewrite a file unchanged")
231	            } else {
232	                let file = gone[rng.below(gone.len())];
233	                state.exists[index(file)] = true;
234	                (file, "re-add a file")
235	            }
236	        }
237	        5 => {
238	            if rng.below(2) == 0 {
239	                state.button_via_index = !state.button_via_index;
240	                (File::Button, "change an import path")
241	            } else {
242	                state.fancy_wraps_card = !state.fancy_wraps_card;
243	                (File::Wrapped, "change the wrapped component")
244	            }
245	        }
246	        6 => {
247	            if rng.below(2) == 0 {
248	                state.toggle_exported = !state.toggle_exported;
249	                (File::Toggle, "toggle an export")
250	            } else {
251	                state.button_exported = !state.button_exported;
252	                (File::Button, "toggle an export")
253	            }
254	        }
255	        _ => {
256	            // Break a file, or fix a broken one.
257	            let file = FILES[rng.below(FILES.len())];
258	            state.broken[index(file)] = !state.broken[index(file)];
259	            (file, if state.broken[index(file)] { "make a file unparsable" } else { "fix a file" })
260	        }
261	    };
262	    touch(state, file);
263	    (file, format!("{what} ({})", file.name()))
264	}
265	
266	fn options(root: &Utf8Path) -> PipelineOptions {
267	    PipelineOptions {
268	        src_dirs: vec![root.to_owned()],
269	        use_cache: false,
270	        html_attributes: HtmlAttributeMode::None,
271	        ..PipelineOptions::default()
272	    }
273	}
274	
275	/// The CLI's canonical JSON (`serde_json::to_string_pretty` of the output), without the run's `stats`, parsed.
276	fn canonical(output: &ExtractionOutput) -> Value {
277	    let mut value: Value = serde_json::from_str(&serde_json::to_string_pretty(output).unwrap()).unwrap();
278	    value.as_object_mut().unwrap().remove("stats");
279	    value
280	}
281	
282	fn rdt_json(output: &ExtractionOutput) -> Value {
283	    serde_json::from_str(&rdt::serialize(output, true).unwrap()).unwrap()
284	}
285	
286	fn same(watched: &ExtractionOutput, cold: &ExtractionOutput, context: &str) {
287	    let (watched, cold_json) = (canonical(watched), canonical(cold));
288	    // Section by section, so a failure prints the component that differs rather than the whole output.
289	    for section in ["components", "enums", "diagnostics"] {
290	        let (a, b) = (&watched[section], &cold_json[section]);
291	        if let (Some(a), Some(b)) = (a.as_object(), b.as_object()) {
292	            assert_eq!(a.keys().collect::<Vec<_>>(), b.keys().collect::<Vec<_>>(), "{section} keys: {context}");
293	            for (key, expected) in b {
294	                assert_eq!(&a[key], expected, "{section}[{key}]: {context}");
295	            }
296	        }
297	        assert_eq!(a, b, "{section}: {context}");
298	    }
299	    assert_eq!(watched, cold_json, "canonical JSON: {context}");
300	}
301	
302	fn seeds() -> Vec<u64> {
303	    match std::env::var("SEED").ok().and_then(|seed| seed.parse().ok()) {
304	        Some(seed) => vec![seed],
305	        None => (1..=SEEDS).collect(),
306	    }
307	}
308	
309	#[test]
310	fn session_equals_cold_after_any_edits() {
311	    let (mut moved, mut steps, mut membership) = (0, 0, 0);
312	    for seed in seeds() {
313	        let dir = tempfile::Builder::new().prefix("SessionEqualsCold").tempdir().unwrap();
314	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
315	        let mut rng = Lcg(seed);
316	        let mut state = State::new();
317	        for file in FILES {
318	            std::fs::write(root.join(file.name()), state.render(file)).unwrap();
319	        }
320	        let options = options(&root);
321	        let eager = WatchSession::new(options.clone());
322	        let initial = eager.initialize();
323	        let lazy = WatchSession::lazy(options.clone());
324	        drop(lazy.initialize());
325	        let mut previous = extract(&options);
326	        same(&initial, &previous, &format!("seed {seed}, before any edit"));
327	        // The lazy session is asked for everything, so each edit has kept answers to go stale.
328	        for key in previous.components.keys() {
329	            drop(lazy.component(key));
330	        }
331	        let mut history: Vec<String> = Vec::new();
332	        for step in 1..=EDITS {
333	            let (file, label) = edit(&mut state, &root, &mut rng);
334	            history.push(label);
335	            let context = format!("seed {seed}, step {step}, edits {history:?}");
336	            let path = root.join(file.name());
337	            drop(eager.update_file(&path));
338	            let delta = lazy.update_file(&path);
339	            let cold = extract(&options);
340	
341	            let watched = eager.snapshot();
342	            same(&watched, &cold, &context);
343	            assert_eq!(rdt_json(&watched), rdt_json(&cold), "rdt: {context}");
344	
345	            let mut lazy_keys = lazy.component_keys();
346	            lazy_keys.sort();
347	            assert_eq!(lazy_keys, cold.components.keys().cloned().collect::<Vec<_>>(), "lazy keys: {context}");
348	            for (key, expected) in &cold.components {
349	                let answer = lazy.component(key).unwrap_or_else(|| panic!("lazy: no {key}: {context}"));
350	                assert_eq!(&answer.entry, expected, "lazy {key}: {context}");
351	            }
352	            // A lazy delta names every component whose entry changed.
353	            for (key, entry) in &cold.components {
354	                if previous.components.get(key) != Some(entry) {
355	                    assert!(
356	                        delta.updated_keys.contains(key),
357	                        "lazy delta misses {key}: {:?}, {context}",
358	                        delta.updated_keys
359	                    );
360	                }
361	            }
362	            // The model is only as strong as the evidence it moves.
363	            moved += usize::from(canonical(&previous) != canonical(&cold));
364	            membership += usize::from(!previous.components.keys().eq(cold.components.keys()));
365	            steps += 1;
366	            previous = cold;
367	        }
368	    }
369	    let total = seeds().len() * EDITS;
370	    assert_eq!(steps, total);
371	    // Many edits change the output, and some add or remove a component (a deleted or broken file, a toggled export);
372	    // without a seed pinned, both must be common or the model is not exercising what it claims.
373	    if total == usize::try_from(SEEDS).unwrap() * EDITS {
374	        assert!(moved * 2 >= total, "only {moved} of {total} edits changed the output");
375	        assert!(membership * 8 >= total, "only {membership} of {total} edits changed the set of components");
376	    }
377	}
