    /// One of `items`, or `None` when there are none: the only way to choose among a list that may be empty.
    fn pick<T: Copy>(&mut self, items: &[T]) -> Option<T> {
        (!items.is_empty()).then(|| items[self.below(items.len())])
    }
}

